import {
  type AdapterCapabilities,
  type AggregateReducer,
  type ColumnMap,
  type GridQuery,
  QueryError,
  type QueryLimits,
  type RowCountMode,
  type RowScope,
} from "@/registry/default/components/data-grid-server-query/data-grid-server-query";
import { type PlanColumn, createGridQuery, likePattern, mapOf, resolveLimits, toSafeText } from "@/registry/default/components/data-grid-server-query/data-grid-server-query-sdk";
import { type Filter, isTextual, renderFilter, treeText } from "./render-postgrest";

type Method = (...args: never[]) => unknown;

/** The caller's Supabase client, such as the one `createClient` returns, typed by shape so the adapter imports no client. */
export type SupabaseClientLike = { from: Method; rpc: Method };

/** The order of a plan as `.order(column, { ascending, nullsFirst })` calls take it. */
export type SupabaseOrder = { column: string; ascending: boolean; nullsFirst: false }[];

export type SupabaseGridQueryOptions<TContext = never> = {
  client: SupabaseClientLike;
  /** The table or view PostgREST exposes. */
  table: string;
  columns: ColumnMap;
  /** Equalities on mapped columns that every query ANDs in. Needs `context` on every call. */
  rowScope?: RowScope<TContext>;
  /** When a rows request also counts the result. Default `"firstBlock"`. */
  rowCount?: RowCountMode;
  limits?: QueryLimits;
  /** IANA zone or fixed offset of day filters on `time` columns. Default `"UTC"`. */
  timeZone?: string;
  /** `"cursor"` pages `fetchRows` by keyset cursors and never counts; every sortable text column then needs `maxLength`. Default `"offset"`. */
  paging?: "offset" | "cursor";
  /**
   * The table's grid function from `grid-query.sql`, such as `"items_grid"`. It answers set values, aggregates, groups,
   * requests whose URL is over `maxUrlLength`, and reads of more rows than `maxRows`. Without it those are `unsupported`,
   * and a long URL is `limit-exceeded`.
   */
  rpc?: string;
  /** The longest request URL the client sends, in characters; a longer request goes to `rpc`. Default 8,000. */
  maxUrlLength?: number;
  /**
   * PostgREST's `max-rows` setting, which cuts every REST answer without an error. Default 1,000, Supabase's default.
   * A read of more rows, the look-ahead row included, goes to `rpc`. Without `rpc`, creation throws when
   * `limits.maxPageSize + 1` exceeds it.
   */
  maxRows?: number;
};

/** One request of the grid function: the plan as one JSON argument. Columns are physical names; the function checks each. */
export type GridFunctionPlan =
  | { kind: "rows"; where: Filter; select: { c: string; text: boolean }[]; order: { c: string; desc: boolean }[]; offset: number; limit: number }
  | { kind: "count"; where: Filter }
  | { kind: "values"; where: Filter; c: string; form: "plain" | "text" | "folded" | "day"; zone: string; pattern: string | null; limit: number }
  | { kind: "aggregates"; where: Filter; columns: GridFunctionAggregate[] }
  /** Under `pivot`, each group also answers `cells`: per key, one value per aggregate. Each key is the filter that keeps its rows. */
  | { kind: "groups"; where: Filter; level: GridFunctionKey; next: GridFunctionKey | null; desc: boolean; offset: number; limit: number; aggregates: GridFunctionAggregate[]; pivot?: { keys: Filter[] } }
  /** The first `limit` keys of `level` in key order, each with the count of all keys as `total`; `values` generated columns per key. */
  | { kind: "pivotKeys"; where: Filter; level: GridFunctionKey; desc: boolean; limit: number; values: number }
  | { kind: "groupCount"; where: Filter; level: GridFunctionKey };
type GridFunctionAggregate = { c: string; reducer: AggregateReducer; blank: boolean };
type GridFunctionKey = { c: string; blank: boolean };

type Result = { data: unknown; error: { message?: unknown } | null; count?: number | null; status?: number };
type Builder = PromiseLike<Result> & {
  or(filters: string): Builder;
  order(column: string, options: { ascending: boolean; nullsFirst: boolean }): Builder;
  range(from: number, to: number): Builder;
  abortSignal(signal: AbortSignal): Builder;
};
type Client = {
  from(relation: string): { select(columns: string, options?: { count?: "exact"; head?: boolean }): Builder };
  rpc(fn: string, args: { plan: GridFunctionPlan }): PromiseLike<Result> & { abortSignal(signal: AbortSignal): PromiseLike<Result> };
};
type Row = Record<string, unknown>;

const IDENTIFIER = /^[A-Za-z_][A-Za-z0-9_]*$/;
const DEFAULT_MAX_URL_LENGTH = 8000;
const DEFAULT_MAX_ROWS = 1000;

const get = (row: unknown, key: string): unknown => (typeof row === "object" && row !== null && Object.hasOwn(row, key) ? (row as Row)[key] : null);
const rowsOf = (data: unknown): unknown[] => (Array.isArray(data) ? data : []);
/** JSON numbers lose int8 and decimal digits, so those columns travel as text. */
const asText = (column: PlanColumn): boolean => column.kind === "number" && (column.numeric === "int8" || column.numeric === "decimal");
const blankText = (column: PlanColumn): boolean => isTextual(column) && !column.keepBlankText;
/** The request URL's length; postgrest-js keeps the URL in its builder's `url`, which its types mark protected. */
function urlLength(builder: Builder): number {
  const url = (builder as { url?: unknown }).url;
  if (typeof url !== "object" || url === null || typeof (url as { href?: unknown }).href !== "string") {
    throw new Error("createSupabaseGridQuery: the client's query builder has no `url`, so the URL length cannot be checked");
  }
  return (url as { href: string }).href.length;
}

async function read(request: PromiseLike<Result>): Promise<Result> {
  const result = await request;
  // A HEAD answer, such as a count's, has no body, so its error has no message.
  if (result.error) throw new Error(`Supabase request failed: ${toSafeText(result.error.message) || `HTTP ${toSafeText(result.status)}`}`);
  return result;
}

/**
 * Reads and counts rows through the caller's Supabase client, from the column map and a request body. It imports no
 * client and sends every filter as one PostgREST logic tree in one `or=(...)`, with every value quoted and escaped.
 *
 * - Set values, aggregates, groups, pivots, requests whose URL is over `maxUrlLength`, and reads of more rows than `maxRows`
 *   run in the table's grid function (`rpc`), which takes the plan as one JSON argument. Without `rpc` they are
 *   `unsupported` or `limit-exceeded`.
 * - A literal `*` in a LIKE test (contains, startsWith, endsWith, case-insensitive equals and set filters, quick search) is
 *   `unsupported-value`: PostgREST reads every `*` of a LIKE value as `%`.
 * - LIKE tests on native enum and uuid columns are `unsupported`: PostgREST cannot cast a filtered column to text.
 * - With a user JWT the browser can call PostgREST directly, so row-level security is the only tenancy boundary;
 *   `rowScope` narrows this layer's own queries.
 * - The grid function takes its plan from the caller and does NOT enforce `rowScope`. A direct caller can read every
 *   column of the wrapper's allow-list, `serverOnly` columns included; only column GRANTs hide a column. Never make
 *   the wrapper SECURITY DEFINER: row-level security would check its owner. Revoke EXECUTE on the wrapper from
 *   `public` and `anon`, and grant it to `authenticated`.
 * - A `where` of `validateChange` is safe only as the sole argument of one `.or()`, as in
 *   `.update(values).or(where).select(pk)`. Joined with another condition in the same `.or()`, the scope becomes one
 *   branch of the OR and stops narrowing.
 * - Writes are not atomic through the adapter: each REST call is its own transaction. Run a whole change in one
 *   consumer RPC, never in a loop of `.update()` calls.
 *
 * @example
 * const columns = defineColumnMap({
 *   id: { type: "number", numeric: "int8", primaryKey: true },
 *   name: { type: "text", searchable: true, maxLength: 200 },
 *   tenantId: { type: "number", numeric: "int4", serverOnly: true },
 * });
 * export const itemsQuery = createSupabaseGridQuery<Item, Session>({ client: supabase, table: "items", columns, rpc: "items_grid", rowScope: (s) => ({ tenantId: s.tenantId }) });
 */
export function createSupabaseGridQuery<TRow = Record<string, unknown>, TContext = never>(options: SupabaseGridQueryOptions<TContext> & { paging: "cursor" }): GridQuery<TRow, TContext, string, SupabaseOrder, string>;
export function createSupabaseGridQuery<TRow = Record<string, unknown>, TContext = never>(options: SupabaseGridQueryOptions<TContext> & { paging?: "offset" }): GridQuery<TRow, TContext, string, SupabaseOrder>;
/** A `paging` known only at run time may page by cursor, so the answer's cursor is typed. */
export function createSupabaseGridQuery<TRow = Record<string, unknown>, TContext = never>(options: SupabaseGridQueryOptions<TContext>): GridQuery<TRow, TContext, string, SupabaseOrder, string>;
export function createSupabaseGridQuery<TRow, TContext>(options: SupabaseGridQueryOptions<TContext>): GridQuery<TRow, TContext, string, SupabaseOrder, string> {
  const { table, columns, rpc } = options;
  const client = options.client as unknown as Client;
  const maxUrlLength = options.maxUrlLength ?? DEFAULT_MAX_URL_LENGTH;
  const timeZone = options.timeZone ?? "UTC";
  if (!Number.isSafeInteger(maxUrlLength) || maxUrlLength <= 0) throw new Error("createSupabaseGridQuery: `maxUrlLength` must be a positive integer");
  // PostgREST reads `,` `.` `(` `)` and `:` in names as grammar, and the grid function names columns by `format('%I')`.
  for (const [what, name] of [["table", table], ["rpc", rpc ?? "grid"]] as const) {
    if (typeof name !== "string" || !IDENTIFIER.test(name)) throw new Error(`createSupabaseGridQuery: \`${what}\` must be a plain identifier (letters, digits, _)`);
  }
  for (const column of mapOf(columns).byId.values()) {
    if (!IDENTIFIER.test(column.field)) throw new Error(`createSupabaseGridQuery: column "${column.id}" has the field "${column.field}", which is not a plain identifier (letters, digits, _)`);
    if (column.operators.size > 0) throw new Error(`createSupabaseGridQuery: column "${column.id}" declares a custom operator, which the Supabase adapter does not render`);
  }
  const maxRows = options.maxRows ?? DEFAULT_MAX_ROWS;
  if (!Number.isSafeInteger(maxRows) || maxRows <= 0) throw new Error("createSupabaseGridQuery: `maxRows` must be a positive integer");
  const maxPageSize = resolveLimits(options.limits).maxPageSize;
  if (rpc === undefined && maxPageSize + 1 > maxRows) throw new Error(`createSupabaseGridQuery: a page of \`limits.maxPageSize\` (${maxPageSize}) rows plus the look-ahead row exceeds \`maxRows\` (${maxRows}), PostgREST's max-rows, which drops rows without an error. Set \`rpc\` to the table's grid function, or set \`limits.maxPageSize\` to ${maxRows - 1} or less.`);
  const anchor = mapOf(columns).tieBreaker[0]!.field;

  const withSignal = <B extends { abortSignal(signal: AbortSignal): unknown }>(builder: B, signal: AbortSignal | undefined): PromiseLike<Result> =>
    (signal ? builder.abortSignal(signal) : builder) as PromiseLike<Result>;
  const callFunction = async (plan: GridFunctionPlan, signal: AbortSignal | undefined, path: readonly (string | number)[]): Promise<unknown> => {
    if (rpc === undefined) throw new QueryError("unsupported", path);
    return (await read(withSignal(client.rpc(rpc, { plan }), signal))).data;
  };
  const filtered = (builder: Builder, filter: Filter): Builder => (filter === true ? builder : builder.or(treeText(filter, anchor)));
  /** Sends the builder when its URL and its row `limit` fit, else the same plan to the grid function. */
  const send = async (builder: Builder, signal: AbortSignal | undefined, plan: () => GridFunctionPlan, limit = 0): Promise<{ rest: Result } | { data: unknown }> => {
    if (urlLength(builder) <= maxUrlLength && limit <= maxRows) return { rest: await read(withSignal(builder, signal)) };
    if (rpc === undefined) throw new QueryError("limit-exceeded", []);
    return { data: await callFunction(plan(), signal, []) };
  };
  const key = (column: PlanColumn): GridFunctionKey => ({ c: column.field, blank: isTextual(column) });
  const aggregatesOf = (list: readonly { column: PlanColumn; reducer: AggregateReducer }[]): GridFunctionAggregate[] =>
    list.map(({ column, reducer }) => ({ c: column.field, reducer, blank: blankText(column) }));
  const byIndex = (list: readonly { column: PlanColumn }[], values: unknown): Row => Object.fromEntries(list.map(({ column }, index) => [column.id, rowsOf(values)[index] ?? null]));

  const capabilities: AdapterCapabilities = {
    caseInsensitiveText: "native",
    likeEscape: true,
    // The adapter refuses a `*` in a LIKE test itself; the core does not read this flag.
    literalAsterisk: false,
    nullsLast: "native",
    aggregates: rpc !== undefined,
    groupBy: rpc !== undefined,
    pivot: rpc !== undefined,
    localDayGrouping: true,
    exactInstantKeys: true,
    millisecondInstantKeys: true,
    nativeLike: false,
  };

  return createGridQuery<TRow, TContext, string, SupabaseOrder, string>({
    columns,
    rowScope: options.rowScope,
    rowCount: options.rowCount,
    limits: options.limits,
    timeZone: options.timeZone,
    paging: options.paging,
    executor: {
      capabilities,
      where: (plan) => treeText(renderFilter(plan.where), anchor),
      orderBy: (plan) => plan.orderBy.map(({ column, direction }) => ({ column: column.field, ascending: direction === "asc", nullsFirst: false })),
      selectRows: async (plan, page) => {
        const filter = renderFilter(plan.where);
        const fields = [...plan.projection, ...(plan.keyText ?? []).map(({ column }) => column)];
        const select = [...new Map(fields.map((column) => [column.field, { c: column.field, text: asText(column) }])).values()];
        let builder = filtered(client.from(table).select(select.map(({ c, text }) => (text ? `${c}::text` : c)).join(",")), filter);
        for (const { column, direction } of plan.orderBy) builder = builder.order(column.field, { ascending: direction === "asc", nullsFirst: false });
        builder = builder.range(page.offset, page.offset + page.limit - 1);
        const order = plan.orderBy.map(({ column, direction }) => ({ c: column.field, desc: direction === "desc" }));
        const sent = await send(builder, page.signal, () => ({ kind: "rows", where: filter, select, order, offset: page.offset, limit: page.limit }), page.limit);
        return rowsOf("rest" in sent ? sent.rest.data : sent.data).map((row) => {
          const out: Row = Object.fromEntries(plan.projection.map((column) => [column.id, get(row, column.field)]));
          for (const { column, as } of plan.keyText ?? []) out[as] = get(row, column.field);
          return out;
        });
      },
      countRows: async (plan, signal) => {
        const filter = renderFilter(plan.where);
        const sent = await send(filtered(client.from(table).select(anchor, { count: "exact", head: true }), filter), signal, () => ({ kind: "count", where: filter }));
        return "rest" in sent ? sent.rest.count : sent.data;
      },
      selectValues: async (plan, { limit, signal }) => {
        const { column } = plan;
        if (column.time && (column.storage !== "native" || /^[+-]/.test(timeZone))) throw new QueryError("unsupported", ["columnId"]);
        const form = column.time ? "day" : !isTextual(column) ? "plain" : column.caseSensitive ? "text" : "folded";
        const pattern = plan.query === "" ? null : likePattern("contains", plan.query, "\\");
        const data = await callFunction({ kind: "values", where: renderFilter(plan.where), c: column.field, form, zone: timeZone, pattern, limit }, signal, ["columnId"]);
        return rowsOf(data).map((entry) => ({ value: get(entry, "value"), count: get(entry, "count") }));
      },
      aggregate: async (plan, signal) => byIndex(plan.columns, await callFunction({ kind: "aggregates", where: renderFilter(plan.where), columns: aggregatesOf(plan.columns) }, signal, [])),
      selectGroups: async (plan, page) => {
        const data = await callFunction(
          {
            kind: "groups",
            where: renderFilter(plan.where),
            level: key(plan.level),
            next: plan.nextLevel ? key(plan.nextLevel) : null,
            desc: plan.direction === "desc",
            offset: page.offset,
            limit: page.limit,
            aggregates: aggregatesOf(plan.aggregates),
            ...(plan.pivot ? { pivot: { keys: plan.pivot.keys.map(({ test }) => renderFilter(test)) } } : {}),
          },
          page.signal,
          ["spec", "groupBy"],
        );
        return rowsOf(data).map((group) => ({
          key: get(group, "key"),
          count: get(group, "count"),
          childCount: get(group, "childCount"),
          aggregates: byIndex(plan.aggregates, get(group, "aggregates")),
          ...(plan.pivot ? { pivotCells: get(group, "cells") as unknown[] } : {}),
        }));
      },
      selectPivotKeys: async (plan, { limit, signal }) => {
        const data = await callFunction({ kind: "pivotKeys", where: renderFilter(plan.where), level: key(plan.level), desc: plan.direction === "desc", limit, values: plan.aggregates.length }, signal, ["spec", "pivot"]);
        return rowsOf(data).map((entry) => ({ key: get(entry, "key"), total: get(entry, "total") }));
      },
      countGroups: async (plan, signal) => callFunction({ kind: "groupCount", where: renderFilter(plan.where), level: key(plan.level) }, signal, ["spec", "groupBy"]),
    },
  });
}

import { QueryError } from "@/registry/default/components/data-grid-server-query/data-grid-server-query";
import { type Operand, type PlanColumn, type Predicate, type Test, isTextual, likePattern } from "@/registry/default/components/data-grid-server-query/data-grid-server-query-sdk";
import { quote } from "./quote";

/** One PostgREST filter on a physical column; `v` is text, as PostgREST reads every value. */
export type FilterLeaf =
  | { c: string; op: "eq" | "neq" | "gt" | "gte" | "lt" | "lte" | "like" | "ilike"; v: string }
  | { c: string; op: "in"; v: string[] }
  | { c: string; op: "is" };
/** A predicate in PostgREST's operators, which the URL and the grid function read alike. PostgREST `not` is plain SQL `NOT`. */
export type FilterNode = { and: FilterNode[] } | { or: FilterNode[] } | { not: FilterNode } | FilterLeaf;
/** `true` and `false` fold away inside groups, so they only stand at the root. */
export type Filter = boolean | FilterNode;

export { isTextual };

function join(key: "and" | "or", items: readonly Filter[]): Filter {
  const neutral = key === "and";
  const out: FilterNode[] = [];
  for (const item of items) {
    if (typeof item === "boolean") {
      if (item !== neutral) return item;
      continue;
    }
    if (Object.hasOwn(item, key)) out.push(...(item as Record<typeof key, FilterNode[]>)[key]);
    else out.push(item);
  }
  if (out.length === 0) return neutral;
  if (out.length === 1) return out[0]!;
  return key === "and" ? { and: out } : { or: out };
}

export const and = (items: readonly Filter[]): Filter => join("and", items);
export const or = (items: readonly Filter[]): Filter => join("or", items);
const not = (item: Filter): Filter => (typeof item === "boolean" ? !item : Object.hasOwn(item, "not") ? (item as { not: FilterNode }).not : { not: item });

/** The operand as PostgREST text: integers and decimals as digits, an epoch instant as its number. */
export function operandText(column: PlanColumn, operand: Operand): string {
  switch (operand.kind) {
    case "text":
    case "date":
    case "number":
      return operand.v;
    case "boolean":
      return String(operand.v);
    case "bigint":
      return operand.v.toString();
    case "instant":
      if (column.storage === "epoch-ms") return String(Date.parse(operand.v));
      if (column.storage === "epoch-s") return String(Date.parse(operand.v) / 1000);
      return operand.v;
  }
}

/**
 * The walker from the core's predicate to PostgREST filters. Only the primary key is known to hold no NULL, so every
 * other column gets the NULL branches the core's semantics need.
 */
export function renderFilter(p: Predicate): Filter {
  return node(p, false);
}

const isNull = (column: PlanColumn): Filter => (column.primaryKey ? false : { c: column.field, op: "is" });
const notNull = (column: PlanColumn): Filter => not(isNull(column));

/** The filter, false on NULL rows when `twoValued`: PostgREST's `not` is SQL `NOT`, which drops a NULL result. */
const twoValuedLeaf = (column: PlanColumn, filter: Filter, twoValued: boolean): Filter => (twoValued ? and([filter, notNull(column)]) : filter);

const value = (column: PlanColumn, operand: Operand): string => operandText(column, operand);

/** A one-element list is an `eq`: PostgREST reads the list `("")` as the empty list. */
const list = (column: PlanColumn, values: readonly string[]): FilterLeaf => (values.length === 1 ? { c: column.field, op: "eq", v: values[0]! } : { c: column.field, op: "in", v: [...values] });

/** `equals` with case is `eq`; every other text test is a LIKE pattern with backslash escapes. */
export function textLeaf(column: PlanColumn, mode: "contains" | "startsWith" | "endsWith" | "equals", text: string, caseSensitive: boolean): FilterLeaf {
  if (mode === "equals" && caseSensitive) return { c: column.field, op: "eq", v: text };
  // PostgREST turns every `*` of a LIKE value into `%`, with no escape for it.
  if (text.includes("*")) throw new QueryError("unsupported-value", [column.id]);
  return { c: column.field, op: caseSensitive ? "like" : "ilike", v: likePattern(mode, text, "\\") };
}

const foldsEmptyText = (column: PlanColumn): boolean => isTextual(column) && !column.keepBlankText && column.native === undefined;
const foldsCase = (column: PlanColumn): boolean => isTextual(column) && column.native === undefined;

function blank(column: PlanColumn, negate: boolean, twoValued: boolean): Filter {
  if (!foldsEmptyText(column)) return negate ? notNull(column) : isNull(column);
  return negate ? twoValuedLeaf(column, { c: column.field, op: "neq", v: "" }, twoValued) : or([isNull(column), { c: column.field, op: "eq", v: "" }]);
}

const guarded = (column: PlanColumn, filter: Filter): Filter => (foldsEmptyText(column) ? and([filter, { c: column.field, op: "neq", v: "" }]) : filter);

function inList(column: PlanColumn, t: Extract<Test, { k: "in" }>, twoValued: boolean): Filter {
  const values = t.values.map((operand) => value(column, operand));
  // A native enum or uuid value is already canonical, and PostgREST has no ILIKE on those types.
  const folded = !t.caseSensitive && foldsCase(column);
  const member = (two: boolean): Filter => (folded ? or(values.map((text) => twoValuedLeaf(column, textLeaf(column, "equals", text, false), two))) : twoValuedLeaf(column, list(column, values), two));
  if (!t.negate) return t.blank ? or([member(twoValued), blank(column, false, twoValued)]) : member(twoValued);
  const outside = folded ? not(member(true)) : not(list(column, values));
  return t.blank ? and([outside, blank(column, true, twoValued)]) : or([isNull(column), outside]);
}

function leafNode(column: PlanColumn, t: Test, twoValued: boolean): Filter {
  const c = column.field;
  switch (t.k) {
    case "eq":
    case "exact":
      return twoValuedLeaf(column, { c, op: "eq", v: value(column, t.value) }, twoValued);
    case "ne":
      return or([isNull(column), { c, op: "neq", v: value(column, t.value) }]);
    case "blank":
      return blank(column, t.negate, twoValued);
    case "text": {
      const filter = textLeaf(column, t.mode, t.text, t.caseSensitive);
      return t.negate ? or([not(filter), isNull(column)]) : twoValuedLeaf(column, filter, twoValued);
    }
    case "cmp":
      return twoValuedLeaf(column, guarded(column, { c, op: t.op, v: value(column, t.value) }), twoValued);
    case "range": {
      const parts: Filter[] = [];
      if (t.lo) parts.push({ c, op: "gte", v: value(column, t.lo) });
      if (t.hi) parts.push({ c, op: t.hiExclusive ? "lt" : "lte", v: value(column, t.hi) });
      return twoValuedLeaf(column, guarded(column, and(parts)), twoValued);
    }
    case "in":
      return inList(column, t, twoValued);
    case "ids": {
      const ids = list(column, t.values.map((operand) => value(column, operand)));
      return t.negate ? not(ids) : ids;
    }
    case "key":
      // No blank guard and no folding: the comparison follows ORDER BY.
      if (t.op === "null" || !t.value) return isNull(column);
      return twoValuedLeaf(column, { c, op: t.op, v: value(column, t.value) }, twoValued);
    case "custom":
      throw new QueryError("unsupported", [column.id]);
  }
}

function node(p: Predicate, twoValued: boolean): Filter {
  switch (p.t) {
    case "true":
      return true;
    case "false":
      return false;
    case "leaf":
      return leafNode(p.column, p.test, twoValued);
    case "not":
      return not(node(p.item, true));
    default:
      return (p.t === "and" ? and : or)(p.items.map((item) => node(item, twoValued)));
  }
}

function leafText(leaf: FilterLeaf): string {
  if (leaf.op === "is") return "is.null";
  if (leaf.op === "in") return `in.(${leaf.v.map(quote).join(",")})`;
  return `${leaf.op}.${quote(leaf.v)}`;
}

const isLeaf = (item: FilterNode): item is FilterLeaf => Object.hasOwn(item, "c");

function nodeText(item: FilterNode): string {
  if (isLeaf(item)) return `${item.c}.${leafText(item)}`;
  if ("and" in item) return `and(${item.and.map(nodeText).join(",")})`;
  if ("or" in item) return `or(${item.or.map(nodeText).join(",")})`;
  const inner = item.not;
  if (isLeaf(inner)) return `${inner.c}.not.${leafText(inner)}`;
  return "not" in inner ? `not.and(${nodeText(inner)})` : `not.${nodeText(inner)}`;
}

/** The logic tree of `.or()`; `anchor` is a column for the constants, which PostgREST has no literal for. */
export function treeText(filter: Filter, anchor: string): string {
  if (filter === true) return `or(${anchor}.is.null,${anchor}.not.is.null)`;
  if (filter === false) return `and(${anchor}.is.null,${anchor}.not.is.null)`;
  return nodeText(filter);
}

import { QueryError } from "@/registry/default/components/data-grid-server-query/data-grid-server-query";

const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/;

/**
 * One value of a PostgREST `or=(...)`, `and=(...)`, or `in.(...)`, always in double quotes. PostgREST reads a backslash
 * as "take the next character", so escaping `"` and `\` leaves the closing quote as the only one that ends the value.
 * An unquoted value would end at `,` or `)`, and `{` would start an array literal. Top-level filters (`.eq()`) never
 * unquote, so this output belongs inside a logic tree only.
 */
export function quote(value: string): string {
  // URL serialization replaces a lone surrogate with U+FFFD, and PostgREST cuts an `in.()` value at its first NUL
  // (`trimNullChars`): either would filter by another value. PostgreSQL text holds no NUL anyway.
  if (LONE_SURROGATE.test(value) || value.includes("\u0000")) throw new QueryError("unsupported-value", []);
  return `"${value.replace(/["\\]/g, "\\$&")}"`;
}

-- The grid function of the gridcn Supabase adapter: `createSupabaseGridQuery({ rpc: "items_grid" })`.
-- Run this file once per database, and again after each update of the add-on; then create one wrapper per table (see the end of the file).
--
-- Trust: the plan comes from the CALLER. PostgREST exposes the wrapper, so any signed-in user can call it with any
-- plan. The function does NOT enforce `rowScope`: row-level security is the only tenancy boundary. A direct caller can
-- read every column of the wrapper's allow-list, `serverOnly` columns included; only column GRANTs hide a column.
--
-- - NEVER make the wrapper or these functions SECURITY DEFINER: row-level security would then check the owner, not the
--   caller, and the caller writes the plan.
-- - Revoke EXECUTE on the wrapper from public and anon, and grant it to authenticated (see the end of the file).
--
-- A value never enters a statement: the statement reads it from the bound plan by JSON path. Only names from the
-- wrapper's allow-list enter it, through format('%I'); operators, reducers, and directions come from closed CASE lists.
-- Every function that validates or builds the statement pins `search_path = pg_catalog, pg_temp`, so the caller's path
-- cannot change a check or a name. `grid_query` runs the statement under the caller's path, so the policies of the
-- caller's tables resolve their names as they do for PostgREST; the statement names every table, function, operator,
-- and type with its schema.

create schema if not exists gridcn;
grant usage on schema gridcn to authenticated;
-- An earlier run of this file left these signatures, which would make the calls below ambiguous.
drop function if exists gridcn.grid_query(regclass, text[], jsonb);
drop function if exists gridcn.grid_sql(regclass, text[], jsonb);
drop function if exists gridcn.check_page(jsonb, boolean);
drop function if exists gridcn.grid_query(regclass, text[], jsonb, int, int, int, int);
drop function if exists gridcn.grid_sql(regclass, text[], jsonb, int, int, int, int);
drop function if exists gridcn.aggregate_sql(regclass, text[], jsonb);

-- Bounds the plan before any catalog lookup: its text in bytes, the nodes of its filter and its pivot keys, and each
-- `in` list.
create or replace function gridcn.check_plan(plan jsonb, max_plan_bytes int, max_nodes int, max_list int)
returns void
language plpgsql immutable security invoker
set search_path = pg_catalog, pg_temp
as $$
begin
  if octet_length(plan::text) > max_plan_bytes then
    raise exception 'gridcn: the plan is over % bytes', max_plan_bytes using errcode = '54000';
  end if;
  if (select count(*) from jsonb_path_query(jsonb_build_array(plan -> 'where', plan -> 'pivot'), 'strict $.** ? (@.type() == "object" || @.type() == "boolean")')) > max_nodes then
    raise exception 'gridcn: the filter has over % nodes', max_nodes using errcode = '54000';
  end if;
  if exists (select 1 from jsonb_path_query(jsonb_build_array(plan -> 'where', plan -> 'pivot'), 'strict $.** ? (@.op == "in")') leaf where jsonb_typeof(leaf -> 'v') = 'array' and jsonb_array_length(leaf -> 'v') > max_list) then
    raise exception 'gridcn: an in list holds over % values', max_list using errcode = '54000';
  end if;
end $$;

-- `value` as a boolean; anything else raises.
create or replace function gridcn.flag(value jsonb, name text)
returns boolean
language plpgsql immutable security invoker
set search_path = pg_catalog, pg_temp
as $$
begin
  if jsonb_typeof(value) is distinct from 'boolean' then
    raise exception 'gridcn: % is a boolean', name using errcode = '22023';
  end if;
  return value = 'true'::jsonb;
end $$;

-- The table `tbl` as a schema-qualified name.
create or replace function gridcn.table_sql(tbl regclass)
returns text
language sql stable security invoker
set search_path = pg_catalog, pg_temp
as $$
  select format('%I.%I', n.nspname, c.relname) from pg_class c join pg_namespace n on n.oid = c.relnamespace where c.oid = tbl
$$;

-- The allowed, live column `name` of `tbl`, qualified by the alias `t` that every statement gives the table, so no
-- output name of the statement shadows it; any other name raises.
create or replace function gridcn.column_sql(tbl regclass, allowed text[], name text)
returns text
language plpgsql stable security invoker
set search_path = pg_catalog, pg_temp
as $$
begin
  -- coalesce: a NULL allow-list or name refuses, never passes.
  if not coalesce(name = any (allowed), false) then
    raise exception 'gridcn: the column is not in the allow-list' using errcode = '42501';
  end if;
  if not exists (select 1 from pg_attribute a where a.attrelid = tbl and a.attname = name and a.attnum > 0 and not a.attisdropped) then
    raise exception 'gridcn: the table has no such column' using errcode = '42703';
  end if;
  return format('t.%I', name);
end $$;

-- The schema-qualified type of a column without its modifier, so a cast never rounds a numeric or cuts a varchar.
create or replace function gridcn.column_type(tbl regclass, name text)
returns text
language sql stable security invoker
set search_path = pg_catalog, pg_temp
as $$
  select format('%I.%I', n.nspname, ty.typname)
  from pg_attribute a join pg_type ty on ty.oid = a.atttypid join pg_namespace n on n.oid = ty.typnamespace
  where a.attrelid = tbl and a.attname = name and a.attnum > 0 and not a.attisdropped
$$;

-- The comparison `op` (`<`, `<=`, `=`, `>=`, `>`) on two values of the column's type. A built-in type, or a domain over
-- one, takes pg_catalog's operator. Any other type takes the operator of its default btree operator class (citext's,
-- an enum's), which only a superuser can create, so an operator planted in the type's schema is never picked.
create or replace function gridcn.operator_sql(tbl regclass, name text, op text)
returns text
language plpgsql stable security invoker
set search_path = pg_catalog, pg_temp
as $$
declare
  typ oid;
  t record;
  found text;
begin
  select a.atttypid into typ from pg_attribute a where a.attrelid = tbl and a.attname = name and a.attnum > 0 and not a.attisdropped;
  loop
    select ty.typtype, ty.typbasetype, ty.typnamespace, ty.typelem, ty.typcategory into t from pg_type ty where ty.oid = typ;
    exit when t.typtype <> 'd';
    typ := t.typbasetype;
  end loop;
  if t.typnamespace = 'pg_catalog'::regnamespace then
    return format('OPERATOR(pg_catalog.%s)', op);
  end if;
  select format('OPERATOR(%I.%s)', n.nspname, o.oprname) into found
  from pg_opclass c
    join pg_am am on am.oid = c.opcmethod and am.amname = 'btree'
    join pg_amop ao on ao.amopfamily = c.opcfamily and ao.amopmethod = am.oid and ao.amoplefttype = c.opcintype and ao.amoprighttype = c.opcintype
      and ao.amopstrategy = array_position(array['<', '<=', '=', '>=', '>'], op)
    join pg_operator o on o.oid = ao.amopopr
    join pg_namespace n on n.oid = o.oprnamespace
  where c.opcdefault and c.opcintype = case
    when t.typtype = 'e' then 'anyenum'::regtype::oid
    when t.typtype = 'r' then 'anyrange'::regtype::oid
    when t.typtype = 'm' then 'anymultirange'::regtype::oid
    when t.typcategory = 'A' and t.typelem <> 0 then 'anyarray'::regtype::oid
    else typ end;
  if found is null then
    raise exception 'gridcn: the column "%" has no default btree operator class', name using errcode = '42883';
  end if;
  return found;
end $$;

-- The SQL of one filter node, PostgREST's operators with PostgREST's semantics (`not` is plain NOT).
create or replace function gridcn.filter_sql(tbl regclass, allowed text[], node jsonb, path text[], depth int default 0)
returns text
language plpgsql stable security invoker
set search_path = pg_catalog, pg_temp
as $$
declare
  op text;
  col text;
  typ text;
  item record;
  parts text[] := '{}';
begin
  if depth > 64 then
    raise exception 'gridcn: the filter is nested too deep' using errcode = '54001';
  end if;
  if jsonb_typeof(node) = 'boolean' then
    return case when node = 'true'::jsonb then 'TRUE' else 'FALSE' end;
  end if;
  if jsonb_typeof(node) is distinct from 'object' then
    raise exception 'gridcn: a filter node is an object or a boolean' using errcode = '22023';
  end if;
  if node ? 'not' or node ? 'and' or node ? 'or' then
    if (select count(*) from jsonb_object_keys(node)) <> 1 then
      raise exception 'gridcn: a group node has one key' using errcode = '22023';
    end if;
    if node ? 'not' then
      return '(NOT ' || gridcn.filter_sql(tbl, allowed, node -> 'not', path || 'not'::text, depth + 1) || ')';
    end if;
    op := case when node ? 'and' then 'and' else 'or' end;
    if jsonb_typeof(node -> op) is distinct from 'array' or jsonb_array_length(node -> op) = 0 then
      raise exception 'gridcn: a group holds a non-empty list' using errcode = '22023';
    end if;
    for item in select e.value, e.ordinality - 1 as i from jsonb_array_elements(node -> op) with ordinality e loop
      parts := parts || gridcn.filter_sql(tbl, allowed, item.value, path || array[op, item.i::text], depth + 1);
    end loop;
    return '(' || array_to_string(parts, case op when 'and' then ' AND ' else ' OR ' end) || ')';
  end if;
  if exists (select 1 from jsonb_object_keys(node) k where k not in ('c', 'op', 'v')) then
    raise exception 'gridcn: a filter leaf holds c, op, and v only' using errcode = '22023';
  end if;
  col := gridcn.column_sql(tbl, allowed, node ->> 'c');
  typ := gridcn.column_type(tbl, node ->> 'c');
  op := node ->> 'op';
  if op = 'is' then
    if node ? 'v' then
      raise exception 'gridcn: is takes no value' using errcode = '22023';
    end if;
    return col || ' IS NULL';
  end if;
  if op = 'in' then
    if jsonb_typeof(node -> 'v') is distinct from 'array' or exists (select 1 from jsonb_array_elements(node -> 'v') e where jsonb_typeof(e) <> 'string') then
      raise exception 'gridcn: in takes a list of texts' using errcode = '22023';
    end if;
    return format('%s %s ANY (CAST(ARRAY(SELECT pg_catalog.jsonb_array_elements_text($1 OPERATOR(pg_catalog.#>) %L)) AS %s[]))', col, gridcn.operator_sql(tbl, node ->> 'c', '='), (path || 'v'::text)::text, typ);
  end if;
  if jsonb_typeof(node -> 'v') is distinct from 'string' then
    raise exception 'gridcn: the operator takes one text value' using errcode = '22023';
  end if;
  if op in ('like', 'ilike') then
    return format('(%s)::pg_catalog.text OPERATOR(pg_catalog.%s) ($1 OPERATOR(pg_catalog.#>>) %L)', col, case op when 'like' then '~~' else '~~*' end, (path || 'v'::text)::text);
  end if;
  -- A btree operator class has no `<>`, so `neq` is NOT `=`, which keeps NULL as NULL alike.
  op := case op when 'eq' then '=' when 'neq' then '=' when 'gt' then '>' when 'gte' then '>=' when 'lt' then '<' when 'lte' then '<=' end;
  if op is null then
    raise exception 'gridcn: unknown operator' using errcode = '22023';
  end if;
  col := format('%s %s CAST(($1 OPERATOR(pg_catalog.#>>) %L) AS %s)', col, gridcn.operator_sql(tbl, node ->> 'c', op), (path || 'v'::text)::text, typ);
  return case when node ->> 'op' = 'neq' then '(NOT ' || col || ')' else col end;
end $$;

-- Raises `message`. Volatile, so the planner never folds it out of a CASE branch that is not taken.
create or replace function gridcn.refuse(message text)
returns text
language plpgsql volatile security invoker
set search_path = pg_catalog, pg_temp
as $$
begin
  raise exception '%', message using errcode = '22023';
end $$;

-- Refuses a pivot key in any shape but the adapter's: `false`, an `eq` or `is` leaf, or `is` OR `eq` for the empty
-- text key. Each key repeats once per aggregate, so a larger tree would multiply past `max_nodes`.
create or replace function gridcn.check_pivot_key(key jsonb)
returns void
language plpgsql immutable security invoker
set search_path = pg_catalog, pg_temp
as $$
begin
  if key = 'false'::jsonb
    or (jsonb_typeof(key) = 'object' and key ->> 'op' in ('eq', 'is'))
    or (jsonb_typeof(key) = 'object' and (select count(*) from jsonb_object_keys(key)) = 1 and jsonb_typeof(key -> 'or') = 'array' and jsonb_array_length(key -> 'or') = 2
      and (key -> 'or' -> 0 ->> 'op') = 'is' and (key -> 'or' -> 1 ->> 'op') = 'eq') then
    return;
  end if;
  raise exception 'gridcn: a pivot key is false, an eq or is leaf, or is OR eq' using errcode = '22023';
end $$;

-- The length of the list `plan -> key`, from `minimum` to 1,000 entries; anything else raises.
create or replace function gridcn.count_of(plan jsonb, key text, minimum int)
returns int
language plpgsql immutable security invoker
set search_path = pg_catalog, pg_temp
as $$
begin
  if jsonb_typeof(plan -> key) is distinct from 'array' or jsonb_array_length(plan -> key) < minimum or jsonb_array_length(plan -> key) > 1000 then
    raise exception 'gridcn: % holds between % and 1,000 entries', key, minimum using errcode = '22023';
  end if;
  return jsonb_array_length(plan -> key);
end $$;

-- `limit`, at most `max_limit`, and `offset` read as bigint from the bound plan; out of range raises.
create or replace function gridcn.check_page(plan jsonb, with_offset boolean, max_limit int)
returns void
language plpgsql immutable security invoker
set search_path = pg_catalog, pg_temp
as $$
begin
  if jsonb_typeof(plan -> 'limit') is distinct from 'number' or (plan ->> 'limit')::numeric not between 0 and max_limit or (plan ->> 'limit')::numeric % 1 <> 0 then
    raise exception 'gridcn: limit is a whole number from 0 to %', max_limit using errcode = '22023';
  end if;
  if with_offset and (jsonb_typeof(plan -> 'offset') is distinct from 'number' or (plan ->> 'offset')::numeric not between 0 and 9007199254740991 or (plan ->> 'offset')::numeric % 1 <> 0) then
    raise exception 'gridcn: offset is a whole number from 0' using errcode = '22023';
  end if;
end $$;

-- `col` as text, with '' read as NULL.
create or replace function gridcn.nonblank_sql(col text)
returns text
language sql immutable security invoker
set search_path = pg_catalog, pg_temp
as $$
  select format('CASE WHEN (%1$s)::pg_catalog.text OPERATOR(pg_catalog.=) '''' THEN NULL ELSE (%1$s)::pg_catalog.text END', col)
$$;

-- The aggregate of one `{ c, reducer, blank }` entry, as text; `blank` reads '' as NULL. With `kept`, over the rows
-- that the SQL condition `kept` keeps.
create or replace function gridcn.aggregate_sql(tbl regclass, allowed text[], entry jsonb, kept text default null)
returns text
language plpgsql stable security invoker
set search_path = pg_catalog, pg_temp
as $$
declare
  col text := gridcn.column_sql(tbl, allowed, entry ->> 'c');
  nonblank text := case when gridcn.flag(entry -> 'blank', 'blank') then gridcn.nonblank_sql(col) else col end;
  rows_sql text := case when kept is null then '' else ' FILTER (WHERE ' || kept || ')' end;
begin
  return case entry ->> 'reducer'
    when 'sum' then format('(pg_catalog.sum(%s)%s)::pg_catalog.text', col, rows_sql)
    when 'avg' then format('(pg_catalog.avg(%s)%s)::pg_catalog.text', col, rows_sql)
    when 'min' then format('(pg_catalog.min(%s)%s)::pg_catalog.text', nonblank, rows_sql)
    when 'max' then format('(pg_catalog.max(%s)%s)::pg_catalog.text', nonblank, rows_sql)
    when 'count' then format('(pg_catalog.count(%s)%s)::pg_catalog.text', nonblank, rows_sql)
    else gridcn.refuse('gridcn: unknown reducer')
  end;
end $$;

-- A group key `{ c, blank }`: the column, with '' read as NULL when `blank`. A timestamp, or a domain over one, keys by
-- its millisecond, the precision of a key on the wire, so the adapter drills a key by the range of its millisecond.
create or replace function gridcn.key_sql(tbl regclass, allowed text[], key jsonb)
returns text
language plpgsql stable security invoker
set search_path = pg_catalog, pg_temp
as $$
declare
  col text := gridcn.column_sql(tbl, allowed, key ->> 'c');
  typ oid;
  t record;
begin
  if gridcn.flag(key -> 'blank', 'blank') then
    return gridcn.nonblank_sql(col);
  end if;
  select a.atttypid into typ from pg_attribute a where a.attrelid = tbl and a.attname = key ->> 'c' and a.attnum > 0 and not a.attisdropped;
  loop
    select ty.typtype, ty.typbasetype into t from pg_type ty where ty.oid = typ;
    exit when t.typtype <> 'd';
    typ := t.typbasetype;
  end loop;
  if typ in ('pg_catalog.timestamp'::regtype, 'pg_catalog.timestamptz'::regtype) then
    return format('pg_catalog.date_trunc(''milliseconds'', %s)', col);
  end if;
  return col;
end $$;

-- The statement of one plan. It holds names and SQL only; `grid_query` runs it with the plan bound as $1.
create or replace function gridcn.grid_sql(tbl regclass, allowed text[], plan jsonb, max_plan_bytes int default 16777216, max_nodes int default 50000, max_list int default 200000, max_limit int default 1001, max_pivot_columns int default 200)
returns text
language plpgsql stable security invoker
set search_path = pg_catalog, pg_temp
as $$
declare
  rel text;
  w text;
  col text;
  key text;
  value_sql text;
  match_sql text;
  list text;
  order_sql text;
  dir text;
  eq text;
  kept text;
  cells text[] := '{}';
  item record;
  entry record;
begin
  perform gridcn.check_plan(plan, max_plan_bytes, max_nodes, max_list);
  rel := gridcn.table_sql(tbl);
  if jsonb_typeof(plan) is distinct from 'object' or not (plan ? 'where') then
    raise exception 'gridcn: the plan is an object with a where' using errcode = '22023';
  end if;
  w := gridcn.filter_sql(tbl, allowed, plan -> 'where', '{where}');
  case plan ->> 'kind'
  when 'rows' then
    perform gridcn.count_of(plan, 'select', 1), gridcn.count_of(plan, 'order', 1), gridcn.check_page(plan, true, max_limit);
    select string_agg(case when gridcn.flag(s.value -> 'text', 'text') then format('(%s)::pg_catalog.text AS %I', gridcn.column_sql(tbl, allowed, s.value ->> 'c'), s.value ->> 'c') else format('%s AS %I', gridcn.column_sql(tbl, allowed, s.value ->> 'c'), s.value ->> 'c') end, ', ' order by s.ordinality)
      into list from jsonb_array_elements(plan -> 'select') with ordinality s;
    select string_agg(gridcn.column_sql(tbl, allowed, o.value ->> 'c') || case when gridcn.flag(o.value -> 'desc', 'desc') then ' DESC NULLS LAST' else ' ASC NULLS LAST' end, ', ' order by o.ordinality)
      into order_sql from jsonb_array_elements(plan -> 'order') with ordinality o;
    return format('SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r)), ''[]''::pg_catalog.jsonb) FROM (SELECT %s FROM %s AS t WHERE %s ORDER BY %s LIMIT ($1 OPERATOR(pg_catalog.->>) ''limit'')::pg_catalog.int8 OFFSET ($1 OPERATOR(pg_catalog.->>) ''offset'')::pg_catalog.int8) r', list, rel, w, order_sql);
  when 'count' then
    return format('SELECT pg_catalog.to_jsonb(pg_catalog.count(*)) FROM %s AS t WHERE %s', rel, w);
  when 'values' then
    perform gridcn.check_page(plan, false, max_limit);
    col := gridcn.column_sql(tbl, allowed, plan ->> 'c');
    case plan ->> 'form'
    when 'plain' then key := col; value_sql := col; match_sql := format('(%s)::pg_catalog.text', col);
    when 'text' then key := format('COALESCE((%s)::pg_catalog.text, '''')', col); value_sql := key; match_sql := format('(%s)::pg_catalog.text', col);
    when 'folded' then key := format('pg_catalog.lower(COALESCE((%s)::pg_catalog.text, ''''))', col); value_sql := format('pg_catalog.min(COALESCE((%s)::pg_catalog.text, ''''))', col); match_sql := format('(%s)::pg_catalog.text', col);
    when 'day' then key := format('(pg_catalog.timezone($1 OPERATOR(pg_catalog.->>) ''zone'', %s))::pg_catalog.date', col); value_sql := key; match_sql := format('(%s)::pg_catalog.text', key);
    else perform gridcn.refuse('gridcn: unknown values form');
    end case;
    if jsonb_typeof(plan -> 'pattern') = 'string' then
      w := format('(%s AND %s OPERATOR(pg_catalog.~~*) ($1 OPERATOR(pg_catalog.->>) ''pattern''))', w, match_sql);
    end if;
    return format('SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(''value'', s.v, ''count'', s.n)), ''[]''::pg_catalog.jsonb) FROM (SELECT (%s)::pg_catalog.text AS v, pg_catalog.count(*) AS n FROM %s AS t WHERE %s GROUP BY %s ORDER BY 2 DESC, 1 LIMIT ($1 OPERATOR(pg_catalog.->>) ''limit'')::pg_catalog.int8) s', value_sql, rel, w, key);
  when 'aggregates' then
    perform gridcn.count_of(plan, 'columns', 0);
    select string_agg(gridcn.aggregate_sql(tbl, allowed, a.value), ', ' order by a.ordinality) into list from jsonb_array_elements(plan -> 'columns') with ordinality a;
    return format('SELECT pg_catalog.jsonb_build_array(%s) FROM %s AS t WHERE %s', coalesce(list, ''), rel, w);
  when 'groups' then
    perform gridcn.count_of(plan, 'aggregates', 0), gridcn.check_page(plan, true, max_limit);
    key := gridcn.key_sql(tbl, allowed, plan -> 'level');
    select string_agg(gridcn.aggregate_sql(tbl, allowed, a.value), ', ' order by a.ordinality) into list from jsonb_array_elements(plan -> 'aggregates') with ordinality a;
    if jsonb_typeof(plan -> 'next') = 'object' then
      col := gridcn.key_sql(tbl, allowed, plan -> 'next');
      value_sql := format('pg_catalog.count(DISTINCT %1$s) OPERATOR(pg_catalog.+) COALESCE(pg_catalog.max(CASE WHEN %1$s IS NULL THEN 1 ELSE 0 END), 0)', col);
    else
      value_sql := 'pg_catalog.count(*)';
    end if;
    dir := case when gridcn.flag(plan -> 'desc', 'desc') then 'DESC' else 'ASC' end;
    if jsonb_typeof(plan -> 'pivot') = 'object' then
      if gridcn.count_of(plan -> 'pivot', 'keys', 0) * gridcn.count_of(plan, 'aggregates', 0) > max_pivot_columns then
        raise exception 'gridcn: the pivot has over % cells per group', max_pivot_columns using errcode = '54000';
      end if;
      -- Each key is a filter tree, so its value stays in the bound plan and compares with the column type's operator.
      for item in select e.value, e.ordinality - 1 as i from jsonb_array_elements(plan -> 'pivot' -> 'keys') with ordinality e loop
        perform gridcn.check_pivot_key(item.value);
        kept := gridcn.filter_sql(tbl, allowed, item.value, array['pivot', 'keys', item.i::text]);
        for entry in select a.value from jsonb_array_elements(plan -> 'aggregates') with ordinality a order by a.ordinality loop
          cells := cells || gridcn.aggregate_sql(tbl, allowed, entry.value, kept);
        end loop;
      end loop;
      eq := case when gridcn.flag(plan -> 'level' -> 'blank', 'blank') then 'OPERATOR(pg_catalog.=)' else gridcn.operator_sql(tbl, plan -> 'level' ->> 'c', '=') end;
      -- The page CTE picks the page's group keys, so the cells reduce only the rows of those groups.
      return format(
        'WITH gridcn_page AS (SELECT %1$s AS k FROM %4$s AS t WHERE %5$s GROUP BY %1$s ORDER BY %1$s %6$s NULLS LAST LIMIT ($1 OPERATOR(pg_catalog.->>) ''limit'')::pg_catalog.int8 OFFSET ($1 OPERATOR(pg_catalog.->>) ''offset'')::pg_catalog.int8) SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(''key'', s.k, ''count'', s.n, ''childCount'', s.c, ''aggregates'', s.a, ''cells'', s.p)), ''[]''::pg_catalog.jsonb) FROM (SELECT (%1$s)::pg_catalog.text AS k, pg_catalog.count(*) AS n, %2$s AS c, pg_catalog.jsonb_build_array(%3$s) AS a, pg_catalog.to_jsonb(ARRAY[%7$s]::pg_catalog.text[]) AS p FROM %4$s AS t WHERE (%5$s) AND ((%1$s) %8$s ANY (SELECT gp.k FROM gridcn_page AS gp) OR ((%1$s) IS NULL AND EXISTS (SELECT 1 FROM gridcn_page AS gp WHERE gp.k IS NULL))) GROUP BY %1$s ORDER BY %1$s %6$s NULLS LAST) s',
        key, value_sql, coalesce(list, ''), rel, w, dir, array_to_string(cells, ', '), eq);
    end if;
    return format(
      'SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(''key'', s.k, ''count'', s.n, ''childCount'', s.c, ''aggregates'', s.a)), ''[]''::pg_catalog.jsonb) FROM (SELECT (%1$s)::pg_catalog.text AS k, pg_catalog.count(*) AS n, %2$s AS c, pg_catalog.jsonb_build_array(%3$s) AS a FROM %4$s AS t WHERE %5$s GROUP BY %1$s ORDER BY %1$s %6$s NULLS LAST LIMIT ($1 OPERATOR(pg_catalog.->>) ''limit'')::pg_catalog.int8 OFFSET ($1 OPERATOR(pg_catalog.->>) ''offset'')::pg_catalog.int8) s',
      key, value_sql, coalesce(list, ''), rel, w, dir);
  when 'pivotKeys' then
    perform gridcn.check_page(plan, false, 1000);
    if jsonb_typeof(plan -> 'values') is distinct from 'number' or (plan ->> 'values')::numeric not between 1 and max_pivot_columns or (plan ->> 'values')::numeric % 1 <> 0 then
      raise exception 'gridcn: values is a whole number from 1 to %', max_pivot_columns using errcode = '22023';
    end if;
    key := gridcn.key_sql(tbl, allowed, plan -> 'level');
    -- A cap below the client's cuts the keys here, so the cells call fits it; `total` still counts every key.
    return format('SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(''key'', s.k, ''total'', s.n)), ''[]''::pg_catalog.jsonb) FROM (SELECT (%1$s)::pg_catalog.text AS k, pg_catalog.count(*) OVER () AS n FROM %2$s AS t WHERE %3$s GROUP BY %1$s ORDER BY %1$s %4$s NULLS LAST LIMIT LEAST(($1 OPERATOR(pg_catalog.->>) ''limit'')::pg_catalog.int8, %5$s)) s',
      key, rel, w, case when gridcn.flag(plan -> 'desc', 'desc') then 'DESC' else 'ASC' end, max_pivot_columns / (plan ->> 'values')::int);
  when 'groupCount' then
    key := gridcn.key_sql(tbl, allowed, plan -> 'level');
    return format('SELECT pg_catalog.to_jsonb(pg_catalog.count(DISTINCT %1$s) OPERATOR(pg_catalog.+) COALESCE(pg_catalog.max(CASE WHEN %1$s IS NULL THEN 1 ELSE 0 END), 0)) FROM %2$s AS t WHERE %3$s', key, rel, w);
  else
    perform gridcn.refuse('gridcn: unknown plan kind');
  end case;
  return null;
end $$;

-- Runs one plan of `createSupabaseGridQuery` against `tbl`, naming only the columns of `allowed`. It sets no
-- search_path, so the caller's policy helpers resolve their unqualified names; it names its own with their schema.
-- The defaults of the caps accept every plan the adapter sends under the core's default limits; a page is 1,000 rows
-- plus the look-ahead row, and a pivot answers at most 200 cells per group. A lower `max_pivot_columns` cuts the pivot
-- keys, and the cut columns count in `pivotOmitted`; keep it at least the value count of a request.
create or replace function gridcn.grid_query(tbl regclass, allowed text[], plan jsonb, max_plan_bytes int default 16777216, max_nodes int default 50000, max_list int default 200000, max_limit int default 1001, max_pivot_columns int default 200)
returns jsonb
language plpgsql stable security invoker
as $$
declare
  result pg_catalog.jsonb;
begin
  execute gridcn.grid_sql(tbl, allowed, plan, max_plan_bytes, max_nodes, max_list, max_limit, max_pivot_columns) into result using plan;
  return result;
end $$;

revoke execute on all functions in schema gridcn from public;
grant execute on all functions in schema gridcn to authenticated;

